        v = y[i] + (rng.expovariate(1.0) - rng.expovariate(1.0)) / 1.4142136 * info['sigma'] * 2.0 * max(min(y[i] - lo[i], hi[i] - y[i]), 0.05 * (hi[i] - lo[i]))
        w = hi[i] - lo[i]
        if w > 0:
            r = (v - lo[i]) % (2.0 * w)
            v = lo[i] + (2.0 * w - r if r > w else r)
        if types[i] == 'integer':
            v = float(round(v))
        v = min(max(v, lo[i]), hi[i])
        y[i] = v
    for i in range(n):
        if types[i] == 'binary' and rng.random() < 0.26:
            y[i] = 1.0 - y[i]
        elif types[i] == 'categorical' and rng.random() < 0.26:
            k = int(hi[i]) + 1
            if k > 1:
                y[i] = float((int(y[i]) + rng.randrange(1, k)) % k)
